import type { Player } from './index';

export const squad: Player[] = [
  // Porteros
  { number: 1, name: 'Lawrence Ati-Zigi', position: 'GK', age: 30, club: 'St Gallen', bio: {"es":"Ati-Zigi nunca quiso ser portero. “Mis amigos me hicieron y he vivido con eso”, dijo. \"Empecé a jugar al fútbol a los seis años como jugador de campo. Pero un día no teníamos portero, así que me metí entre los postes y eso fue todo\". No hace falta decir que el cambio dio sus frutos. Ha tenido una carrera muy sólida en selecciones, representando a su país en tres Afcons (2019, 2021, 2023) y siendo titular en el Mundial de Qatar 2022. Se erige como el portero con más experiencia de la plantilla este verano, ya que debutó en 2018, siete años antes que el actual número uno, Benjamin Asare. Siempre ha sido un aficionado al dibujo y la pintura, lo que le ayuda a mantenerse fresco en el campo. \"Los errores en el fútbol no me molestan\", afirmó. \"Lo más importante es mantener la calma. Y mi hobby encaja muy bien con eso. Me encanta dibujar todo lo que me viene a la mente, incluidas muchas cosas divertidas\".","en":"Ati-Zigi never really wanted to be a keeper. “My friends made me, and I have lived with it,” he said. “I started playing football at the age of six as an outfield player. But one day we didn’t have a keeper, so I went between the posts, and that was it.” It goes without saying that the switch paid off. He has had a very solid national team career, representing his country at three Afcons (2019, 2021, 2023) and being first-choice at the 2022 World Cup in Qatar. He stands as the most experienced keeper in the squad this summer, having made his debut in 2018, seven years before the current number one, Benjamin Asare. He has always been a fan of drawing and painting, which helps him stay cool on the pitch. \"Errors in football don't upset me,\" he said. \"The most important thing is to keep calm. And my hobby fits very well with that. I love drawing everything that comes into my mind, including lots of fun things.\""}, special: "Keen painter" },
  { number: 12, name: 'Joseph Anang', position: 'GK', age: 25, club: 'St Patrick\'s Athletic', bio: {"es":"Anang, ex portero de Inglaterra sub-20, surgió como una opción poco probable para Ghana en mayo del año pasado cuando fue convocado para la Unity Cup en Brentford en Londres. Su debut se produjo el pasado noviembre en una derrota por 2-0 ante Japón en la Copa Kirin. Sólido portero con rápidos reflejos, nació en Accra pero se mudó a Inglaterra con su familia cuando era adolescente. \"Mis padres viajaron al extranjero en diferentes momentos para conseguir una vida mejor para nuestra familia\", dijo en 2024. \"Mi padre era electricista y se fue a Estados Unidos, pero ahora se jubiló, luego mi madre se mudó al Reino Unido para trabajar primero como limpiadora, luego hizo un curso de enfermería y trabajó en una residencia para personas con demencia. Viví con mis abuelos, mi única hermana y mis dos hermanos, y seguí a mi madre aquí unos años más tarde\". Firmó un acuerdo de beca con el West Ham en 2017, pero no logró un gran avance en el primer equipo en siete años allí. Después de sólidas cesiones en Stevenage y St Patrick's, firmó un contrato permanente con el club de la Premier Division de la Liga de Irlanda en 2024.","en":"A former England Under-20 keeper, Anang emerged as an unlikely option for Ghana in May last year when he was called up for the Unity Cup at Brentford in London. His debut came last November in a 2-0 loss to Japan in the Kirin Cup. A solid shot-stopper with quick reflexes, he was born in Accra but moved to England with his family as a teenager. “My parents both went abroad at different times to get a better life for our family,” he said in 2024. “My dad was an electrician and went to the US, but he has now retired, then my mum moved to the UK to work first as a cleaner, then she did a nursing course and worked in a care home for people with dementia. I lived with my grandparents and my one sister and two brothers, and followed my mum here a few years later.” He signed a scholarship deal with West Ham in 2017 but did not make a first-team breakthrough in seven years there. After solid loan spells at Stevenage and St Patrick’s, he signed a permanent deal with the League of Ireland Premier Division club in 2024."} },
  { number: 16, name: 'Benjamin Asare', position: 'GK', age: 33, club: 'Hearts of Oak', bio: {"es":"Mientras estaba en los rivales de Hearts of Oak, Great Olympics, en junio de 2021, Asare se rompió la pierna en el derbi contra sus empleadores actuales. Se perdió 18 meses del fútbol y le aconsejaron que considerara la posibilidad de retirarse, pero tuvo una recuperación notable y al cabo de dos años era el portero titular de Ghana. Su incorporación al equipo nacional fue un avance notable. Después de que Ghana concediera siete goles en seis partidos y terminara última en el grupo de clasificación de Afcon 2025, Asare fue reclutado, uno de una serie de cambios. Esto lo convirtió, a los 32 años, en el jugador de mayor edad del Hearts of Oak en debutar en Ghana, y el primero de sus porteros en representar a la selección nacional en 20 años. Su impacto fue sorprendente: cuatro porterías a cero en cinco partidos mientras Ghana aseguraba la clasificación para la Copa del Mundo. En noviembre del año pasado detuvo el penalti de Hwang Hee-chan en la Copa Kirin contra Corea del Sur, consolidando su creciente reputación.","en":"While at Hearts of Oak’s rivals, Great Olympics, in June 2021, Asare broke his leg in the derby against his current employers. He missed 18 months of football and was advised to consider retiring, but made a remarkable comeback, and within two years was Ghana’s first-choice goalkeeper. His introduction to the national team was a remarkable breakthrough. After Ghana conceded seven goals in six games and finished bottom of the Afcon 2025 qualifying group, Asare was drafted in, one of a raft of changes. It made him, at 32, the oldest Hearts of Oak player to make his Ghana debut, and the first of their keepers to represent the national side for 20 years. His impact was stunning: four clean sheets in five matches as Ghana secured World Cup qualification. In November last year he saved Hwang Hee-chan’s penalty in the Kirin Cup against South Korea, cementing his growing reputation."}, special: "No 1 goalkeeper" },
  // Defensores
  { number: 2, name: 'Alidu Seidu', position: 'DF', age: 26, club: 'Rennes', bio: {"es":"Seidu, formado en la Academia Jean-Marc Guillou de Costa de Marfil, se unió al Clermont Foot en 2019 y debutó con el primer equipo un año después. En 2024 se mudó a Rennes con un contrato de cuatro años, pero sufrió una lesión del ligamento cruzado anterior en noviembre. Ha sido un largo camino de regreso. \"Fue duro porque tenía mucho dolor\", le dijo a Ouest France. \"Pero rápidamente lo vi como un desafío. He pasado por cosas peores... Crecí en una zona muy dura y muy violenta. Estar rodeado de amigos que llevaban ese estilo de vida y andar por las calles me hacía un poco agresivo, mezquino. Caminábamos por las calles con cuchillos o machetes, cometía robos, vandalismo y tráfico de poca monta. Mi madre siempre estaba llorando y, a veces, me escapaba por las noches para evitar que mi padre me castigara\". Cuando fue atacado con un machete durante una pelea tuvo que pasar tres meses en el hospital. \"Perdí mucha sangre, no podía hablar... Todo el mundo pensaba que iba a morir. Así que tengo suerte de haberme convertido en jugador, de estar aquí. Siempre trato de convertir el lado negativo en algo positivo, está en mi carácter. Mi tío me empujó hacia el fútbol porque sabía que tenía algo. Siempre me apoyó y el fútbol me salvó la vida\".","en":"Educated at the Jean-Marc Guillou Academy in Ivory Coast, Seidu joined Clermont Foot in 2019, and made his first-team debut a year later. In 2024 he moved to Rennes on a four-year deal, but suffered an ACL injury that November. It has been a long road back. “It was tough because I was in a lot of pain,” he told Ouest France. “But I quickly saw it as a challenge. I have been through worse … I grew up in a very tough, very violent area. Being around friends who were into that lifestyle and hanging out on the streets made me a bit aggressive, mean. We walked the streets with knives or machetes, I committed thefts, vandalism, and small-time trafficking. My mother was always crying, and sometimes I ran away at night to avoid my father punishing me.” When he was attacked with a machete during a fight he had to spend three months in hospital. “I lost a lot of blood, I couldn’t speak… Everyone thought I was going to die. So I’m lucky to have become a player, to be here. I always try to turn the negative side into something positive, it’s in my character. My uncle pushed me towards football because he knew I had something. He always supported me, and football saved my life.”"}, special: "Survivor" },
  { number: 4, name: 'Jonas Adjetey', position: 'DF', age: 22, club: 'Wolfsburg', bio: {"es":"Después de hacer 29 aperturas en 32 apariciones en su gran campaña y disfrutar de cuatro años con el Basilea, Adjetey se mudó a Wolfsburg por 10 millones de euros a principios de este año, y progresó rápidamente, mejorando su consistencia, sincronizando mejor sus tacleadas y perfeccionando balones largos en diagonal. Su desarrollo y la desafortunada lesión del ligamento cruzado anterior de Mohammed Salisu lo han convertido casi en una elección automática para Ghana este verano. Tuvo una educación dura en Teshie, un suburbio de Accra. \"Realmente no teníamos mucho\", dijo al sitio web del Wolfsburg. \"Vas a la escuela, juegas al fútbol y ayudas a tus padres. Tres cosas, todos los días\". Cuando necesitaba botas de fútbol, ​​tenía que levantarse a las 5 de la mañana e ir a una obra con sus amigos. \"Tuve que trabajar. Ayudé allí para poder pagarlos\". Luego perdió a su padre en un accidente automovilístico. “Me entristece mucho que ya no pueda presenciar aquello en lo que invirtió tanto tiempo y pasión… Mis padres dieron todo por mi hermana y por mí”.","en":"After making 29 starts in 32 appearances in his breakthrough campaign and enjoying four years with Basel, Adjetey moved to Wolfsburg for a reported €10m at the start of this year, and made swift progress, improving his consistency, timing his tackles better, and perfecting long diagonal balls. His development, and Mohammed Salisu’s unfortunate ACL injury, have made him almost an automatic pick for Ghana this summer. He had a tough upbringing in Teshie, a suburb of Accra. “We didn’t really have much,” he told Wolfsburg’s website. “You go to school, play football and help your parents. Three things, every day.” When he needed football boots he had to get up at 5am and go to a construction site with his friends. “I had to work. I helped out there so I could afford them.” Then he lost his father in a car accident. “I am very sad that he can no longer witness what he invested so much time and passion in … My parents gave everything for my sister and me.”"}, special: "Fighter" },
  { number: 6, name: 'Abdul Mumin', position: 'DF', age: 28, club: 'Rayo Vallecano', bio: {"es":"Era incierto si Mumin llegaría a América del Norte. No volvió al fútbol competitivo hasta abril, después de 13 meses de baja por una lesión del ligamento cruzado anterior. Sufrió la lesión justo cuando se encontraba en un período dorado de forma, demostrando ser uno de los jugadores más consistentes del Rayo, y lo dejó enfrentando meses de agotadora rehabilitación. Pero llegó allí, y el entrenador internacional Carlos Queiroz estaba decidido a incluirlo por su conocimiento de La Liga, su compostura y su dominio aéreo. También es un sólido modelo a seguir. En 2024, cuando el Rayo venció al Atlético de Lugones por 6-0 en la primera ronda de la Copa del Rey, Mumin pasó el descanso jugando al fútbol con los recogepelotas del club anfitrión y posando para fotos con ellos. El club publicó en línea más tarde: \"Siempre estaremos felices por el éxito de Abdul. Nuestros recogepelotas no han olvidado su amable gesto de jugar con ellos durante el entretiempo del partido de Copa del Rey\".","en":"It was touch and go whether Mumin would make it to North America. He only returned to competitive football in April after 13 months out following an anterior cruciate ligament injury. He sustained the injury just as he was in a golden spell of form, proving himself one of Rayo’s most consistent performers, and left him facing months of gruelling rehabilitation. But he got there – and international coach Carlos Queiroz was determined to include him for his La Liga know-how, composure and aerial dominance. He’s a solid role model, too. In 2024, when Rayo beat minnows Atlético de Lugones 6-0 in the Copa del Rey first round, Mumin spent half-time playing football with the host club’s ballboys and posing for photos with them. The club posted online later: “ We will always be happy for Abdul's success. Our ballboys haven't forgotten his kind gesture of playing with them during halftime of the Copa del Rey match.”"} },
  { number: 14, name: 'Gideon Mensah', position: 'DF', age: 28, club: 'Auxerre', bio: {"es":"Uno de los jugadores más experimentados del equipo Black Stars, que debutó en 2019 contra Sudáfrica en un clasificatorio para Afcon 2021 en Cape Coast. Sin embargo, tiene un error, razón por la cual el entrenador de Ghana, Otto Addo, ha probado otras cinco opciones en el lateral izquierdo, probando con Patrick Kpozo, Ebenezer Annan, Derrick Köhn, Abdul Fatawu Hamidu e Isaac Afful. Pero la experiencia y la positividad de Mensah cuentan mucho. En 2019 estuvo a punto de realizar la cesión de sus sueños al Barcelona, ​​para ser suplente de Jordi Alba. Cuando su agente le habló de la oferta, recordó en 2024: “No pude resistirme a pensar en el próximo vuelo a España”. Pero el acuerdo colapsó cuando se filtró la noticia del acuerdo, violando un acuerdo de confidencialidad. \"Al día siguiente, en todas partes de Ghana se difundió la noticia de que el Barcelona me quería\", dijo a Flashscore. \"Pero nadie sabe qué podría pasar en el futuro. La oportunidad podría volver a aparecer\". Su biografía de Instagram: \"Sigue orando, sigue planificando, sigue presionando\".","en":"One of the most experienced players in the Black Stars squad, having made his debut in 2019 against South Africa in an Afcon 2021 qualifier in Cape Coast. He does, though, have an error in him, which is why Ghana’s coach, Otto Addo, has been through five other options in the left-back slot, trying Patrick Kpozo, Ebenezer Annan, Derrick Köhn, Abdul Fatawu Hamidu and Isaac Afful. But Mensah’s experience and positivity count for a lot. In 2019 he nearly made a dream loan move to Barcelona, to be deputy to Jordi Alba. When his agent told him about the offer, he recalled in 2024: “I couldn’t resist thinking about the next flight to Spain”. But the deal collapsed when news of the agreement leaked, breaching a confidentiality agreement. “The next day the news was everywhere in Ghana that Barcelona wanted me,” he told Flashscore. “But nobody knows what could happen in the future. The opportunity could come back again.” His Instagram bio: “Keep Praying, Keep Planning, Keep Pushing.”"}, special: "Experienced" },
  { number: 17, name: 'Baba Rahman', position: 'DF', age: 32, club: 'PAOK', bio: {"es":"El exdefensa del Chelsea está de regreso con Ghana después de una larga ausencia, habiendo estado en un exilio autoimpuesto desde 2023 cuando fue abucheado por los aficionados durante un partido de clasificación de la Afcon contra la República Centroafricana en Kumasi. Le dijo a Joy Sports el año pasado: \"Los abucheos no me afectaron durante el partido; como profesional, aprendes a lidiar con eso. Pero después del pitido final, mientras caminaba hacia el autobús del equipo, realmente lo entendí. Fue difícil de aceptar. Así que sentí que era el momento adecuado para concentrarme en mi cuerpo y recuperarme adecuadamente\". Su excelente forma en Grecia la temporada pasada significa que regresó a la selección nacional este verano con confianza. Pasó ocho años en los libros del Chelsea, de 2015 a 2023, pero solo hizo 23 apariciones y pasó la mayor parte de ese tiempo cedido o en recuperación después de sufrir dos lesiones graves en la rodilla. Estuvo a punto de darse por vencido después del segundo, en 2019. \"Le dije a mi familia que lo dejaba\", le dijo a la BBC en 2024. \"Pero el doctor Paco [Biosca, ex director médico del Chelsea] dijo que había visto a otros jugadores regresar y me prometió que si era paciente y mentalmente fuerte también podría hacerlo. Me quedé dormido y luego decidí que quería luchar por mi carrera. Estoy agradecido de que el fútbol me haya dado una segunda oportunidad. Intentando disfrutarlo hasta el último momento.\"","en":"The former Chelsea defender is back for Ghana after a long absence, having been in self-imposed exile since 2023 when he was booed by fans during an Afcon qualifier against Central African Republic in Kumasi. He told Joy Sports last year: “The booing didn’t affect me during the match – as a professional, you learn to deal with that. But after the final whistle, as I walked to the team bus, it really sank in. It was tough to take. So I felt it was the right time to focus on my body and recover properly.” His fine form in Greece last season means he returned to the national set-up this summer in a confident mood. He spent eight years on Chelsea’s books from 2015 to 2023 but only made 23 appearances, spending most of that time on loan or in recovery having suffered two serious knee injuries. He nearly gave up after the second, in 2019. \"I said to my family I was quitting,\" he told the BBC in 2024. \"But Dr Paco [Biosca, ex-Chelsea medical director] said that he had seen other players come back and promised that if I was patient and mentally strong that I could do it too. I slept on it and then decided I wanted to fight for my career. I am grateful that football has given me a second chance. I'm just trying to enjoy it to the last moment.\""} },
  { number: 18, name: 'Jerome Opoku', position: 'DF', age: 28, club: 'Basaksehir', bio: {"es":"Opoku, nacido en Lambeth, ha seguido una ruta nómada hasta la cima. Producto de la academia del Fulham, sufrió una lesión del ligamento cruzado anterior a los 17 años, luego estuvo cedido en tres ocasiones, en Accrington Stanley, Plymouth y el Vejle danés antes de unirse al Arouca portugués en 2022. De allí se mudó al Estambul Basaksehir de Turquía en 2023. Desde entonces, su forma ha sido impresionante y se le vinculó con un regreso a la Premier League durante la última ventana de invierno. Él le restó importancia. “Como siempre digo, es el plan de Dios, así que creo que si sigo haciendo las actuaciones, lo que venga reflejará dónde podría estar o dónde debería estar”, dijo a World Soccer Talk. “Por ahora estoy aquí en Estambul y eso es en lo que estoy concentrado, pero pase lo que pase es realmente el plan de Dios”. Hizo su debut en Ghana en 2023 y dijo que conseguir la clasificación para la Copa Mundial el año pasado fue \"simplemente increíble... cuando estaba en ese campo, y una vez que sonó el silbato, miré a mi alrededor, vi las caras de todos, vi las caras de mi familia... Me hizo sentir como si fuera parte de algo mucho más grande que solo el fútbol. Ves lo mucho que significa literalmente para todos en el país\".","en":"Lambeth-born Opoku has had a nomadic route to the top. A Fulham academy product, he suffered an ACL injury aged 17, then had three loan spells, at Accrington Stanley, Plymouth and Danish side Vejle before joining Portuguese side Arouca in 2022. He moved from there to Turkey’s Istanbul Basaksehir in 2023. His form since has been impressive, and he was linked with a return to the Premier League during the last winter window. He played it down. “As I always say, it’s God’s plan, so I think that if I just keep putting in the performances, whatever comes will kind of reflect on where I could be, or where I should be,” he told World Soccer Talk. “For now, I’m here in Istanbul, and that’s what I’m focused on, but whatever happens is really God’s plan.” He made his Ghana debut in 2023, and said securing World Cup qualification last year was “just amazing … when I was on that pitch, and once the whistle went, I looked around me, I saw everyone's faces, I saw my family's faces … It made me feel like I was a part of something much bigger than just football. You see how much it means to literally everyone in the country.”"} },
  { number: 21, name: 'Kojo Peprah Oppong', position: 'DF', age: 22, club: 'Nice', bio: {"es":"Ha sido un ascenso meteórico. Hace sólo tres años todavía estaba en la segunda división del fútbol ghanés, con la Attram De Visser Academy, un club copropiedad del ex Black Star, Godwin Attram. Ese verano se marchó al IFK Norrköping sueco, donde, a través de una cesión en el GIF Sundsvall, rápidamente demostró su potencial, hasta el punto de que en agosto del año pasado el Niza pagó 2,5 millones de euros para ficharlo. Florian Maurice, director deportivo del Niza, dijo: \"Lo que nos atrajo de él no fue sólo su velocidad, su movilidad y su agresividad en los duelos, sino también su capacidad para jugar en diferentes sistemas\". Se instaló rápidamente, jugó liga y fútbol europeo, y pronto se le vinculó con clubes de la Premier League. \"Estoy sorprendido\", dijo Oppong a Get French Football News el año pasado. \"No esperaba jugar tanto al principio, pero ahora estoy jugando mucho y espero mucho de mí mismo\". Hizo su debut con Ghana en el partido de clasificación para el Mundial contra Comoras en Accra en octubre pasado. Su futuro parece brillante.","en":"It has been a meteoric rise. Only three years ago he was still in the second tier of Ghanaian football, with Attram De Visser Academy, a club co-owned by the former Black Star, Godwin Attram. That summer he left for Swedish side IFK Norrköping, where, via a loan spell at GIF Sundsvall, he quickly proved his potential – so much so that in August last year Nice paid €2.5m to sign him. Florian Maurice, sporting director at Nice, said: “What drew us to him was not only his speed, his mobility and his aggression in duels, but also his ability to play in different systems.” He settled fast, playing league and European football, and was soon being linked with Premier League clubs. “I’m surprised,” Oppong told Get French Football News last year. “I didn’t expect to play this much in the beginning, but I’m now playing a lot – and I expect a lot from myself.” He made his Ghana debut in the World Cup qualifier against Comoros in Accra last October. His future looks bright."}, special: "Going places" },
  { number: 23, name: 'Derrick Luckassen', position: 'DF', age: 31, club: 'Pafos', bio: {"es":"Ha sido todo un viaje hasta este Mundial. Nacido en Ámsterdam, Luckassen comenzó en la academia juvenil del AZ y allí logró su gran avance en el club senior. Se unió a su rival PSV con un contrato de cinco años en 2017, luego tuvo una serie de préstamos en Hertha y Anderlecht, luego en los clubes turcos Kasimpasa y Fatih Karagumruk. Se mudó a Chipre con el Pafos en 2024, ayudándolos a ganar el título en su primera temporada y, el 5 de noviembre de 2025, fue su gol de cabeza el que le dio al club su primera victoria en la Liga de Campeones propiamente dicha: una sorprendente victoria por 1-0 en la fase de liga sobre el Villarreal. Después de representar a los Países Bajos a nivel juvenil sin lograr ningún gran avance en la selección absoluta, finalmente recibió su primera convocatoria de Ghana en marzo. Hizo el corte final para este verano cuando Alexander Djiku fue descartado por una lesión en el tendón de la corva.","en":"It’s been quite a journey to this World Cup. Born in Amsterdam, Luckassen started out at AZ’s youth academy and made his senior club breakthrough there. He joined rivals PSV on a five-year deal in 2017, then had a series of loans, at Hertha and Anderlecht, then Turkish clubs Kasimpasa and Fatih Karagumruk. He moved to Cyprus with Pafos in 2024, helping them win the title in his first season, and, on 5 November 2025, it was his headed goal that gave the club their first ever win in the Champions League proper – a shock league stage 1-0 victory over Villarreal. After representing the Netherlands at youth level without making a senior breakthrough, he finally received his first Ghana call-up this March. He made the final cut for this summer when Alexander Djiku was ruled out with a hamstring injury."} },
  { number: 26, name: 'Marvin Senaya', position: 'DF', age: 25, club: 'Auxerre', bio: {"es":"A principios de año, no muchos hubieran esperado que el jugador de 25 años estuviera en el equipo de la Copa del Mundo, pero, después de haber debutado con la selección nacional en marzo contra Austria, destacó contra Gales en mayo y ahora está compitiendo por un lugar en el once inicial. El lateral derecho nacido en Francia comenzó en Estrasburgo y ascendió en las ligas, incluido un período en Suiza con Lausana, antes de unirse al Auxerre en 2025. Podría haber elegido jugar para Togo: su padre es Yao Mawuko Senaya, que jugó 26 partidos internacionales con su país natal entre 1998 y 2008. En marzo, Marvin se convirtió en uno de los pocos futbolistas que han sido convocados para dos selecciones nacionales. La misma ventana internacional ya que tanto Ghana como Togo lo incluyeron en sus equipos. \"Me siento profundamente honrado de representar a mi país\", dijo. \"Ghana tiene una rica historia futbolística y vestiré la camiseta con orgullo, lealtad y compromiso\".","en":"At the start of the year not many would have expected the 25-year-old to be in the World Cup squad but, having made his national team debut in March against Austria, he excelled against Wales in May and is now competing for a spot in the starting XI. The France-born right-back started out at Strasbourg and has worked his way up the leagues – including a spell in Switzerland with Lausanne – before he joined Auxerre in 2025. He could have chosen to play for Togo – his father is Yao Mawuko Senaya, who won 26 caps for the country of his birth between 1998 and 2008. In March, Marvin became one of only a few footballers to have been called up to two national teams for the same international window as both Ghana and Togo included him in their squads. “I feel deeply honoured to represent my country,” he said. “Ghana has a rich footballing history and I will wear the shirt with pride, loyalty and commitment.”"}, special: "Late call-up" },
  // Volantes
  { number: 3, name: 'Caleb Yirenkyi', position: 'MF', age: 20, club: 'FC Nordsjælland', bio: {"es":"Otro producto de la famosa Academia Right to Dream, Yirenkyi se unió al FC Nordsjælland danés en 2024 y fue el brindis de los fanáticos de Ghana después de dos apariciones en la Copa Kirin del año pasado. Un jugador poderoso, hábil y versátil, experto en el área por área o como lateral derecho, a menudo se le compara con Michael Essien, que ahora es uno de sus entrenadores en Dinamarca. Sobre la influencia de Essien, Yirenkyi dice: \"Él puede entrenar e impactar a todos y a cualquiera. Aprendemos mucho de él y estamos muy agradecidos de tener a un tipo así\". Yirenkyi llegó a la Copa del Mundo después de meses de especulaciones sobre transferencias que lo vinculaban con los equipos más importantes de Inglaterra. Su compañero de club y equipo internacional, Prince Amoako Junior, dijo a Joy Sports en enero: \"Él no se ve a sí mismo como nosotros lo vemos porque es un tipo muy humilde. Pero Caleb está loco, es increíblemente bueno. Es una superestrella, y se lo digo siempre\".","en":"Another product of the famous Right to Dream Academy, Yirenkyi joined Danish side FC Nordsjælland in 2024 and was the toast of Ghana fans after two appearances in last year’s Kirin Cup. A powerful, skilful and versatile performer, adept box-to-box or as a right-wing back, he is often compared to Michael Essien, who is now one of his coaches in Denmark. On Essien’s influence, Yirenkyi says: “He can coach and impact everyone and anyone. We learn a lot from him and are very grateful to have such a guy.” Yirenkyi arrived at the World Cup after months of transfer speculation linking him with England’s biggest sides. His club and international teammate Prince Amoako Junior told Joy Sports in January: “He doesn’t see himself the way we see him because he’s a very humble guy. But Caleb is insane, he’s crazily good. He’s a superstar, and I tell him so every time.”"}, special: "One to watch" },
  { number: 5, name: 'Thomas Partey', position: 'MF', age: 32, club: 'Villarreal', bio: {"es":"Partey, que forma parte de la selección de Ghana desde hace una década, está en su segundo Mundial. Un poderoso mediocampista defensivo, ganó la Europa League y apareció en la final de la Liga de Campeones de 2016 con el Atlético de Madrid, y se convirtió en el jugador ghanés más caro de la historia cuando se unió al Arsenal cuatro años después por £45 millones. Cuatro días después de dejar el Arsenal rumbo al Villarreal en 2025, fue acusado de cinco cargos de violación y un cargo de agresión sexual relacionados con presuntos incidentes entre 2021 y 2022. Partey se declaró inocente de todos esos cargos en el Tribunal de la Corona de Southwark en septiembre, donde se fijó la fecha del juicio para el 2 de noviembre de 2026. En febrero de este año se enfrentó a dos nuevos cargos de violación después de que otra mujer se presentara ante la policía. En abril se declaró inocente de esas dos acusaciones de violación. Su abogada defensora, Jenny Wiltshire, dijo: \"Thomas Partey sigue negando todos los cargos contra él. Ha cooperado con la policía en todo momento\".","en":"Part of the Ghana side for a decade, Partey is at his second World Cup. A powerful defensive midfielder, he won the Europa League and appeared in the 2016 Champions League final with Atlético Madrid, and became the most expensive Ghanaian player ever when he joined Arsenal four years later for £45m. Four days after he left Arsenal for Villarreal in 2025 he was charged with five counts of rape and one count of sexual assault relating to alleged incidents between 2021 and 2022. Partey pleaded not guilty to all those charges at Southwark crown court in September, where a trial date was set for 2 November 2026. In February of this year he faced two new counts of rape after another woman came forward to police. In April he pleaded not guilty to those two allegations of rape. His defence lawyer, Jenny Wiltshire, said: “Thomas Partey continues to deny all charges against him. He has cooperated with the police throughout.”"} },
  { number: 8, name: 'Kwasi Sibo', position: 'MF', age: 28, club: 'Real Oviedo', bio: {"es":"Hasta hace poco, Kwasi era el menos conocido de los hermanos Sibo. Su hermano Simon siempre fue el centro de atención, ya que fue capitán del equipo local Liberty Professionals y representó a las selecciones juveniles de Ghana a finales de la década de 2010. Sin embargo, Kwasi realmente lo eclipsó después de ayudar al Real Oviedo a asegurar el ascenso a La Liga por primera vez en 24 años. Pero no es que Simon haya concedido la supremacía. \"Cuando vengo de vacaciones, Simon todavía me entrena\", dice Kwasi. \"Sigue siendo mi entrenador y, de vez en cuando, ¡me enseña uno o dos trucos! Pero jugar para Ghana es la realización de un sueño familiar. Mis hermanos siempre quisieron que uno de nosotros jugara para las Estrellas Negras\". El nombre Sibo en el idioma Lambossie (del grupo étnico Sissala en la región del Alto Oeste de Ghana) significa una gran familia de guerreros, y Kwasi es fiel a eso: combativo, atlético e implacable con el balón.","en":"Until fairly recently, Kwasi was the lesser-known of the Sibo brothers. His brother Simon always drew the focus, having captained local side Liberty Professionals and represented Ghana’s youth national teams in the late 2010s. However, Kwasi truly upstaged him after helping Real Oviedo to secure La Liga promotion for the first time in 24 years. Not that Simon has conceded supremacy, though. “When I come down for holidays, Simon still trains me,” says Kwasi. “He is still my coach, and every now and then, he will teach me a trick or two! But me playing for Ghana is the fulfilment of a family dream. My brothers have always wanted one of us to play for the Black Stars.” The name Sibo in the Lambossie language (of the Sissala ethnic group in Ghana’s Upper West Region) means a big family of warriors, and Kwasi is true to that: combative, athletic and relentless on the ball."} },
  { number: 15, name: 'Elisha Owusu', position: 'MF', age: 28, club: 'Auxerre', bio: {"es":"Nacido en Francia de padres ghaneses, Owusu comenzó en la academia de Lyon. Firmó su primer contrato profesional con ellos en 2017, pero no logró gran avance allí, sino que se mudó cedido al Sochaux en 2018 y luego a Bélgica con el Gent un año después. Se unió al actual club Auxerre en 2023. Líder sólido y confiable en el mediocampo, ha capitaneado al Auxerre y aporta muchos conocimientos a este equipo. Hizo su debut internacional en el repechaje del Mundial de 2022 contra Nigeria y en febrero habló de su ambición. \"Sería una gran bendición jugar el Mundial, pero trato de no pensar demasiado en ello. Para mí la vida es un proceso. Lo tomo día a día y dejo el resto a Dios\".","en":"Born in France to Ghanaian parents, Owusu started out in Lyon’s academy. He signed his first professional deal with them in 2017, but didn’t make a breakthrough there, moving instead to Sochaux on loan in 2018, then to Belgium with Gent a year later. He joined current club Auxerre in 2023. A solid, dependable leader in midfield, he has captained Auxerre and brings plenty of know-how to this squad. He made his international debut in the 2022 World Cup play-off tie against Nigeria, and spoke in February about his ambition. “It would be a big blessing to play in the World Cup, but I try not to think about it too much. For me life is about process. I take it day by day, and leave the rest to God.”"} },
  { number: 20, name: 'Augustine Boakye', position: 'MF', age: 26, club: 'Saint-Étienne', bio: {"es":"Boakye dejó el fútbol ghanés en 2021 y firmó un contrato de cuatro años con el club austriaco Wolfsberger AC. Tras mudarse a Saint-Étienne tres años después, habló abiertamente de una de sus mayores ambiciones. \"Sería un sueño jugar para mi país, pero no voy a exigirlo ni a decir que tengo que hacerlo. La convocatoria podría llegar hoy o mañana, no sé cuándo, pero cuando llegue, será bueno y estaré listo\". Tuvo que esperar, pero valió la pena: su primera convocatoria llegó como parte del equipo de este verano. Sabe que su papel es alimentar a los delanteros. \"Soy un número 10 al que le encanta ayudar. Lo que más me gusta es ayudar a mi delantero porque creo que cuando el delantero marca más le da más confianza al equipo. Veo al delantero como el hombre principal y cuando no marca y se frustra, eso afecta a todo el equipo\". El héroe de la infancia de Boakye fue el excentrocampista de Ghana Sulley Muntari. \"Él era mi ídolo cuando era niño porque mi madre lo amaba mucho. Así que yo lo observaba y también lo amaba\".","en":"Boakye left Ghanaian football in 2021, signing a four-year deal at Austrian club Wolfsberger AC. After moving to Saint-Étienne three years later, he spoke openly about one of his biggest ambitions. “It would be a dream to play for my country, but I’m not going to demand it and say I have to. The call-up could come today or tomorrow, I don’t know when – but when it comes, it will be good, and I will be ready.” He was made to wait, but it was worth it: his first call-up coming as part of this summer’s squad. He knows his role is to feed the forwards. “I am a No10 who loves to assist. I love it most when I assist my striker because I think that when the striker scores more it gives the team more confidence. I see the striker as the main man and so when he’s not scoring and he gets frustrated it affects the whole team.” Boakye’s childhood hero was former Ghana midfielder Sulley Muntari. “He was my idol growing up because my mum loved him so much. So I watched him, and also loved him.”"} },
  // Delanteros
  { number: 7, name: 'Abdul Fatawu', position: 'FW', age: 21, club: 'Leicester', bio: {"es":"Capaz de algunos momentos extraordinarios, incluidos tres goles desde la línea media, uno para los sub-20 de Ghana, uno para los sub-23 y uno para Leicester contra Ipswich en diciembre del año pasado, que, medido al menos 65 yardas, fue el gol de campeonato de mayor alcance registrado. Su entrenador en ese momento, Martí Cifuentes, dijo: \"Es un momento brillante de Abdul. Lo intenta mucho en los entrenamientos. Le gusta buscar esas situaciones. Siempre se esfuerza por ser mejor\". Fatawu le dijo a la BBC: \"Siempre intento esto desde larga distancia, y cuando lo acerté no tuve ninguna duda. Me siento increíble\". Sufrió una lesión del ligamento cruzado anterior en noviembre de 2024, pero se recuperó, demostró su forma y nuevamente se le vinculó con clubes de la Premier League.","en":"Capable of some extraordinary moments, including three goals from the halfway line, one for Ghana’s under-20s, one for the under-23s, and one for Leicester against Ipswich in December last year which, measured at least 65 yards, was the longest-range Championship goal on record. His manager at the time, Marti Cifuentes, said: “It’s a brilliant moment from Abdul. He tries it a lot in training. He likes to look for those situations. He always pushes himself to be better.” Fatawu told the BBC: “I always try this from long range, and when I hit this one I didn’t have any doubts. I feel amazing.” He sustained an ACL injury in November 2024 but worked his way back, proved his form, and has again been linked with Premier League clubs."}, special: "Long-range shooter" },
  { number: 9, name: 'Jordan Ayew', position: 'FW', age: 34, club: 'Leicester', captain: true, bio: {"es":"Después de 16 años en la selección nacional, Ayew llega este verano tras una agotadora temporada en el club Leicester, al que se unió procedente de Palace en 2024. Pero si bien sus actuaciones han sido variadas en Inglaterra mientras los Foxes luchaban, su forma consistentemente productiva con Ghana ha demostrado el papel clave que aún puede desempeñar a nivel internacional, con siete goles y seis asistencias durante la clasificación para la Copa del Mundo. También recibió la capitanía, y luego dijo: \"Estoy viviendo un sueño y no sé cuándo terminará. Nunca pensé que sería capitán, nunca estuvo en mi mente, pero creo en el destino y espero más\". Es el tercer Ayew que ha sido capitán de las Estrellas Negras después de su legendario padre Abedi, que llevó el brazalete de 1992 a 1998, y su hermano mayor, André, capitán de 2019 a 2024.","en":"After 16 years in the national team, Ayew arrives this summer on the back of a gruelling club season with Leicester, whom he joined from Palace in 2024. But while his displays have been mixed in England as the Foxes struggled, his consistently productive form for Ghana has shown what a key role he can still play at international level, with seven goals and six assists during World Cup qualifying. He was also given the captaincy, saying later: “I am living a dream and I don’t know when it will end. I never thought I would become captain, it was never in my mind, but I believe in destiny and I’m hoping for more.” He is the third Ayew to have captained the Black Stars after his legendary father Abedi, who wore the armband from 1992 to 1998, and his older brother, André, captain from 2019 to 2024."} },
  { number: 10, name: 'Brandon Thomas-Asante', position: 'FW', age: 27, club: 'Coventry City', bio: {"es":"Han sido 12 meses prolíficos para Thomas-Asante. En mayo pasado, abrió su cuenta internacional contra Nigeria en la Unity Cup 2025 y, un año después, ayudó a encabezar la campaña por el título del campeonato de Coventry con 13 goles en 33 apariciones. Ha sido un ascenso notable para un jugador que ascendió de rango desde la Liga Nacional Inglesa y jugará fútbol de primera categoría después de 10 temporadas como profesional senior. \"Tengo muchas ganas de mantener la cabeza gacha y estar preparado porque me apasiona mucho mi nación\", dijo Thomas-Asante al dirigirse a su primer gran torneo después del éxito con Coventry. Ha sido recompensado por sus grandes esfuerzos esta temporada con la icónica camiseta número 10 de Ghana, que anteriormente vistió Stephen Appiah, quien capitaneó a las Estrellas Negras hasta su récord en cuartos de final de la Copa del Mundo en 2010, y André Ayew.","en":"It has been a prolific 12 months for Thomas-Asante. Last May, he opened his international account against Nigeria in the 2025 Unity Cup, and a year later, he helped spearhead Coventry’s Championship title charge with 13 goals in 33 appearances. It has been a remarkable rise for a player who rose through the ranks from the English National League and will play top-flight football after 10 seasons as a senior professional. “I’m really eager to keep my head down, keep ready because I’m so passionate about my nation,” Thomas-Asante said on heading to his first major tournament after success with Coventry. He has been rewarded for his great efforts this season with the iconic Ghana No 10 shirt, previously donned by Stephen Appiah, who captained the Black Stars to their World Cup record quarter-final finish in 2010, and André Ayew."} },
  { number: 11, name: 'Antoine Semenyo', position: 'FW', age: 25, club: 'Manchester City', bio: {"es":"Arsenal, Millwall, Reading y Tottenham rechazaron a Semenyo cuando era joven, y Palace lo dejó ir a los 15 años después de ocho semanas de prueba. \"Nunca en mi vida me había sentido tan molesto por el fútbol. Le lloraba a mi padre\", le dijo a The Guardian en 2024. \"Dejé de jugar durante un año, solo me concentré en la escuela\". Pero, a través de un programa de academia juvenil, obtuvo una prueba en Bristol City en 2017 y firmó su primer contrato profesional allí. Tuvo tres préstamos antes de establecerse, luego se unió a Bournemouth por £ 10 millones en 2023 y al Man City por £ 64 millones en enero. “A veces aparecen en mi teléfono recuerdos de cuando estaba cedido y los comparo con los de ahora”, dijo. \"Haces un viaje al pasado y piensas: 'Vaya, has recorrido un largo camino'\". Tiene la palabra 'elegido' tatuada en la espalda. Le dijo a GQ: \"Miré los tatuajes del [baloncestista] Jayson Tatum: tiene el nombre de la calle en la que creció y otras cosas, y decía 'elegido' en su espalda. Pensé, ¿sabes qué? Esto se parece a mí. Me siento como el elegido, siento que Dios me ha elegido para estar en esta posición\".","en":"Arsenal, Millwall, Reading and Tottenham turned Semenyo down as a youngster, and Palace let him go at 15 after eight weeks on trial. “I’ve never been so upset in my life about football. I was crying to my dad,” he told The Guardian in 2024. “I stopped playing for a year, just focused on school.” But, via a youth academy programme he earned a trial at Bristol City in 2017 and signed his first professional contract there. He had three loans spells before establishing himself, then joined Bournemouth for £10m in 2023, and Man City for £64m in January. “Sometimes I get memories flash up on my phone from when I was out on loan, and I compare them with now,” he said. “You go on a trip down memory lane and it is like: ‘Wow, you’ve come a long way.’” He has the word ‘chosen’ tattooed on his back. He told GQ: “I looked at [basketballer] Jayson Tatum's tattoos – he has the name of the street he grew up on and other stuff, and it said ‘chosen’ on his back. I was like, you know what? This resembles me. I feel like the chosen one, I feel like God's chosen me to be in this position.”"}, special: "Super star" },
  { number: 13, name: 'Christopher Bonsu Baah', position: 'FW', age: 22, club: 'Al-Qadsiah', bio: {"es":"Bonsu-Baah, bendecido con ritmo, control cercano y notable habilidad para regatear, ha sido muy valorado durante mucho tiempo, con algunos de los clubes más importantes del mundo rodeándolo cuando solo tenía 14 años. \"Me permitieron probar en todas partes: en el Borussia Dortmund, Barcelona, ​​Manchester United... Pero como aún no tenía 18 años, no pude conseguir un contrato profesional. Es bueno que tenga mucha paciencia\", le dijo a De Zondag. En 2023, dejó el equipo de nivel inferior Shooting Stars en Ghana por Sarpsborg en Noruega, pero se quedó solo cuatro meses antes de que el Genk de la Pro League belga lo contratara por cinco años. El año pasado cambió Bélgica por el Al-Qadsiah de Arabia Saudita, dirigido por Brendan Rodgers, y debutó con las Black Stars.","en":"Blessed with pace, close control and remarkable dribbling ability, Bonsu-Baah has long been highly rated, with some of the world’s biggest clubs circling him when he was just 14. \"I was allowed to trial everywhere: at Borussia Dortmund, Barcelona, Manchester United … But because I was not yet 18, I couldn’t get a professional contract. It’s good that I have a lot of patience,\" he told De Zondag. In 2023, he left the lower-tier side Shooting Stars in Ghana for Sarpsborg in Norway, but stayed just four months before Belgian Pro League side Genk signed him on a five-year deal. Last year he swapped Belgium for Saudi Arabia’s Al-Qadsiah, managed by Brendan Rodgers, and made his Black Stars debut."} },
  { number: 19, name: 'Iñaki Williams', position: 'FW', age: 32, club: 'Athletic Bilbao', bio: {"es":"En 2021, Williams rechazó las propuestas iniciales de la Asociación de Fútbol de Ghana. Ya había jugado una vez con España, en un amistoso de 2016, y le dijo a The Guardian: \"Nací en Bilbao. Nunca olvidaré mis raíces familiares, pero me siento vasco y no puedo estafar a nadie. No creo que sería correcto ocupar el lugar de alguien que realmente lo merece y que siente Ghana al 100%\". Pero cuando Ghana volvió a llamar después de asegurarse la clasificación para el Mundial de 2022, Williams cambió de opinión. \"Todavía no lo tenía claro hasta que fui a Ghana con mis padres, mi familia y mi novia. Fuimos a ver el país, la familia en Accra y Kumasi. Fue emotivo, como si toda la ciudad estuviera esperando cuando me bajé del auto. Fue increíble, increíble. Y ahí fue donde todo cambió. Fue entonces cuando fui a hablar con mi abuelo. Le dije que había una posibilidad de que pudiera jugar con Ghana en la Copa del Mundo y qué pensaba. Él dijo de inmediato que no Le quedaba mucho tiempo para vivir y soñaba con que su nieto jugara con Ghana. Entonces no había nada en qué pensar”. Su hermano menor Nico también juega en el Athletic de Bilbao y en España.","en":"In 2021 Williams declined initial overtures from the Ghana Football Association. He had played once for Spain already, in a 2016 friendly, and told The Guardian: “I was born in Bilbao. I won’t ever forget my family roots, but I feel Basque and can’t con anyone. I don’t think it would be right to take the place of someone who really deserves it and who feels Ghana 100%.” But when Ghana came calling again having secured World Cup qualification in 2022, Williams changed his mind. “I still wasn’t clear about it until I went to Ghana with my parents, my family and girlfriend. We went to see the country, the family in Accra and Kumasi. It was emotional, like the whole city was waiting when I got out of the car. It was incredible, incredible. And that’s where everything changed. That’s when I went to talk to my grandad. I told him there was a chance that I could play for Ghana at the World Cup and what did he think. He said straight away that he didn’t have long left to live and he dreamed of his grandson playing for Ghana. There was nothing left to think about then.” His younger brother Nico also plays for Athletic Bilbao, and for Spain."}, special: "Goal threat" },
  { number: 22, name: 'Kamaldeen Sulemana', position: 'FW', age: 24, club: 'Atalanta', bio: {"es":"Puro ritmo. Durante un cameo en la segunda mitad contra Uruguay en la Copa del Mundo de 2022, el extremo Sulemana registró 22,18 mph, el tiempo más rápido registrado por cualquier jugador en el torneo, superando a los veloces Alphonso Davies y Nico Williams. “Ni siquiera corría rápido”, reflexionó más tarde. \"Fue cuando yo estaba corriendo hacia atrás, ya sabes, estábamos abajo 2-0, y luego faltaban como cinco minutos para el final, y hubo un contraataque en nuestra contra, así que tuve que cubrirme\". Se unió al Atalanta procedente de Southampton por £ 22 millones y está en su sexto año con las Black Stars, siendo esta su segunda Copa del Mundo y su cuarto torneo importante en general. Solía ​​ser conocido por su atlética celebración de gol con volteretas hacia atrás, ya que le enseñaron gimnasia y fútbol en la Academia Right to Dream de Ghana. Pero ya no. \"Mis padres me dijeron que no lo hiciera más porque es peligroso\", dijo en octubre del año pasado. \"Lo hice contra la Juventus, pero fue sólo una descarga de adrenalina, espontánea. No lo volveré a hacer\".","en":"Pure pace. During a second-half cameo against Uruguay in the 2022 World Cup, winger Sulemana clocked 22.18mph, the fastest time recorded by any player at the tournament, surpassing the lightning-quick Alphonso Davies and Nico Williams. “I wasn’t even running fast,” he reflected later. “It was when I was running back, you know, we were down 2-0, and then it was like five minutes to go, and there was a counter against us, so I had to cover back.\" He joined Atalanta from Southampton for £22m and is in his sixth year with the Black Stars, with this his second World Cup and fourth major tournament overall. He used to be known for his athletic backflip goal celebration, having been taught gymnastics as well as football at Ghana’s Right to Dream Academy. But no longer. “My parents told me not to do it any more because it’s dangerous,” he said in October last year. “I did it against Juventus, but it was just an adrenaline rush, spontaneous. I won’t do it again.”"}, special: "Lightning quick" },
  { number: 24, name: 'Ernest Nuamah', position: 'FW', age: 23, club: 'Lyon', bio: {"es":"Nuamah surgió como uno de los talentos ofensivos más prometedores de Ghana en Right to Dream, una de las academias más prestigiosas de África Occidental. Después de desarrollar su estilo creativo y dinámico en Dinamarca, fichó cedido por el Lyon antes de fichar permanentemente por el club de la Ligue 1. En 2024, se llegó a un acuerdo con Fulham, pero la medida fracasó después de que Nuamah desapareciera durante su examen médico. Su agente confirmó el profundo afecto del jugador por el Lyon, lo que llevó al propietario del club, John Textor, a disculparse por intentar presionar al extremo para que realizara la transferencia. En 2025 se rompió el ligamento cruzado anterior y un año después solo necesitó tres apariciones como suplente en su club para convencer a Carlos Queiroz de que debía ir al Mundial. El joven de 22 años dice: \"Deberías esperar el Nuamah que conoces. He entrenado muy duro y, con el apoyo de mis compañeros de equipo, creo que estoy listo para dar todo lo que pueda por esta nación. No ha sido fácil para mí lesionarme. He trabajado muy duro para llegar a este punto y no puedo esperar para darlo todo\".","en":"Nuamah emerged as one of Ghana’s most promising offensive talents from Right to Dream, one of West Africa’s most prestigious academies. After developing his creative and pace-driven style in Denmark, he joined Lyon on loan before signing permanently with the Ligue 1 club. In 2024, a deal with Fulham had been agreed but the move collapsed after Nuamah disappeared during his medical. His agent confirmed the player’s deep affection for Lyon, leading to the club owner, John Textor, to apologise for attempting to pressure the winger into the transfer. In 2025, he ruptured his anterior cruciate ligament and a year later he needed only three substitute appearances for his club to convince Carlos Queiroz that he should go to the World Cup. The 22-year-old says: “You should expect the Nuamah you know. I’ve trained very hard, and with the support of my teammates, I think I’m ready to give everything I can for this nation. It hasn’t been easy for me, getting an injury. I’ve worked really hard to get to this point and I can’t wait to give my all.”"} },
  { number: 25, name: 'Prince Kwabena Adu', position: 'FW', age: 23, club: 'Viktoria Plzen', bio: {"es":"Hace seis años, Kwabena Adu, entonces en el Bechem United de Ghana, fue incluido en la lista Next Generation del Guardian de 60 de los mejores talentos jóvenes del fútbol mundial. Pero en 2021, justo antes de partir para representar a Ghana en la Copa Africana de Naciones Sub-20, sufrió una lesión de ligamentos que puso en peligro su carrera y que lo mantuvo fuera durante dos años. \"Fue un momento realmente difícil en mi vida\", dijo Adu a Flashscore el año pasado. \"Fue duro, así que volví a mi ciudad natal para quedarme allí y relajar mi mente. En ese momento ya no pensaba en volver a jugar al fútbol. Estar lesionado durante un período tan largo me hizo cuestionarme muchas cosas\". Pero se recuperó, recuperó su forma y su forma física y se mudó al gigante checo Viktoria Plzen en agosto de 2024. Su ícono: \"Mi estilo es muy similar al de Luis Suárez, así que veo mucho sus videos. La forma en que Suárez anota, corre, sus movimientos, con y sin balón, y fuera de la cancha. Me gusta todo de él y realmente aprendo mucho de él. Incluso todavía lo veo en la MLS\".","en":"Six years ago Kwabena Adu, then at Ghana’s Bechem United, was named on the Guardian’s Next Generation list of 60 of the best young talents in world football. But in 2021, just before leaving to represent Ghana at the Under-20s Africa Cup of Nations he sustained a career-threatening ligament injury which kept him out for two years. \"It was a really difficult moment in my life,\" Adu told Flashscore last year. \"It was tough so I went back to my hometown to stay there and relax my mind. At that point I wasn't thinking about playing football again. Being injured for such a long period made me question a lot of things.\" But he did recover, working his way back to form and fitness, and made a move to Czech giants Viktoria Plzen in August 2024. His icon: \"My style is very similar to Luis Suárez so I watch his videos a lot. The way Suárez scores, runs, his movement, with and without the ball, and off the pitch. I like everything about him and really learn a lot from him. I even still watch him in the MLS.”"} },
];

